INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2710354, 377236, 62578, '<td valign="top">well done</td>', 'well done', '2006-08-09 11:18:00.000000', NULL, 1),
(2710355, 377346, 62578, '<td valign="top">got your feet wet on that one!  nicely done</td>', 'got your feet wet on that one!  nicely done', '2006-08-09 11:18:28.000000', NULL, 1),
(2710357, 376453, 52336, '<td valign="top">That''s pretty cool... minimalist somehow, and interesting.  Overall flat, so would really have benefitted from adjustment layers to improve contrast and enhance colours.  But an elegant image for me, well thought out.</td>', 'That''s pretty cool... minimalist somehow, and interesting.  Overall flat, so would really have benefitted from adjustment layers to improve contrast and enhance colours.  But an elegant image for me, well thought out.', '2006-08-09 11:18:37.000000', NULL, 1),
(2710359, 375262, 51538, '<td valign="top">Nicely dramatic.  The sky seems perfect for the pose. 9.</td>', 'Nicely dramatic.  The sky seems perfect for the pose. 9.', '2006-08-09 11:18:46.000000', NULL, 1),
(2710365, 376610, 51538, '<td valign="top">That is a sort of primeval location.  The fast shutter speed works very well.  Your exposure is extremely effective.  I reckon it was a difficult shot to take. 9.</td>', 'That is a sort of primeval location.  The fast shutter speed works very well.  Your exposure is extremely effective.  I reckon it was a difficult shot to take. 9.', '2006-08-09 11:19:56.000000', NULL, 1),
(2710367, 374997, 49672, '<td valign="top">Hmmm...great perspective, great idea - but what are the blotches that look like clouds?  Still, pretty good shot.</td>', 'Hmmm...great perspective, great idea - but what are the blotches that look like clouds?  Still, pretty good shot.', '2006-08-09 11:20:43.000000', NULL, 1),
(2710369, 377233, 52336, '<td valign="top">Great capture as I''m sure you know.  Lovely overall, well done.</td>', 'Great capture as I''m sure you know.  Lovely overall, well done.', '2006-08-09 11:21:18.000000', NULL, 1),
(2710371, 376696, 62578, '<td valign="top">You will get some flack for this...trust me, I did it too!!  It''s a good choice, but try to play with lighting and composition. Nice attempt though! Oh...and don''t let them discourage you, keep trying!</td>', 'You will get some flack for this...trust me, I did it too!!  It''s a good choice, but try to play with lighting and composition. Nice attempt though! Oh...and don''t let them discourage you, keep trying!', '2006-08-09 11:21:21.000000', NULL, 1),
(2710373, 375443, 62578, '<td valign="top">lovely, I love the color against the dirty, run down look of the tressel.</td>', 'lovely, I love the color against the dirty, run down look of the tressel.', '2006-08-09 11:21:58.000000', NULL, 1),
(2710374, 376606, 49672, '<td valign="top">Wow, really neat sky.  I think I''d like it even more without the tree, or with the tree silhouetted.</td>', 'Wow, really neat sky.  I think I''d like it even more without the tree, or with the tree silhouetted.', '2006-08-09 11:22:00.000000', NULL, 1),
(2710376, 375247, 50641, '<td valign="top">Very nice sky.</td>', 'Very nice sky.', '2006-08-09 11:22:02.000000', NULL, 1),
(2710377, 376348, 62578, '<td valign="top">that''s cool</td>', 'that''s cool', '2006-08-09 11:22:07.000000', NULL, 1),
(2710379, 373868, 62578, '<td valign="top">a little over-sharpened...nice idea though</td>', 'a little over-sharpened...nice idea though', '2006-08-09 11:22:42.000000', NULL, 1),
(2710381, 377273, 50641, '<td valign="top">funny and well-captured</td>', 'funny and well-captured', '2006-08-09 11:22:49.000000', NULL, 1),
(2710382, 375981, 52336, '<td valign="top">Very, very pretty, lovely dutone, but I''m not sure about it''s suitability for the challenge.  The border for me is too heavy and dark for such a delicate subject.  Otherwise, a beautiful image.</td>', 'Very, very pretty, lovely dutone, but I''m not sure about it''s suitability for the challenge.  The border for me is too heavy and dark for such a delicate subject.  Otherwise, a beautiful image.', '2006-08-09 11:22:53.000000', NULL, 1),
