(2712334, 377298, 61073, '<td valign="top">Not sure if this was your intent but the whole image is very grainy</td>', 'Not sure if this was your intent but the whole image is very grainy', '2006-08-09 20:54:12.000000', NULL, 1),
(2712337, 377615, 61073, '<td valign="top">Beautiful</td>', 'Beautiful', '2006-08-09 20:54:40.000000', NULL, 1),
(2712344, 375025, 61073, '<td valign="top">Picture would be better if it was larger..hard to see detail</td>', 'Picture would be better if it was larger..hard to see detail', '2006-08-09 20:57:10.000000', NULL, 1),
(2712345, 376805, 61073, '<td valign="top">Picture is way too small..</td>', 'Picture is way too small..', '2006-08-09 20:57:29.000000', NULL, 1),
(2712347, 376696, 51793, '<td valign="top">There is nothing that really stands out here and the date... Take the date out of the picture.</td>', 'There is nothing that really stands out here and the date... Take the date out of the picture.', '2006-08-09 20:58:33.000000', NULL, 1),
(2712349, 376020, 61073, '<td valign="top">Wow you got really close to the ground to spray insecticide..haha.  Neat idea.</td>', 'Wow you got really close to the ground to spray insecticide..haha.  Neat idea.', '2006-08-09 20:58:37.000000', NULL, 1),
(2712351, 376020, 51793, '<td valign="top">A little blury,</td>', 'A little blury,', '2006-08-09 20:59:01.000000', NULL, 1),
(2712354, 376696, 61073, '<td valign="top">Ok..there are a couple of things you notice right off. First of course is the date stamp which I am sure everyone will comment on..it is a must to remove the date stamp. There is a corner of something black on the left side of the picture which is distracting, perhaps cropping that out would help. Also the background isn''t flattering with your subject. The lamp idea may have potential but you just have to give it the proper enhancements &amp; environment.</td>', 'Ok..there are a couple of things you notice right off. First of course is the date stamp which I am sure everyone will comment on..it is a must to remove the date stamp. There is a corner of something black on the left side of the picture which is distracting, perhaps cropping that out would help. Also the background isn''t flattering with your subject. The lamp idea may have potential but you just have to give it the proper enhancements & environment.', '2006-08-09 21:01:22.000000', NULL, 1),
(2712362, 377443, 61073, '<td valign="top">Pretty..</td>', 'Pretty..', '2006-08-09 21:03:54.000000', NULL, 1),
(2712387, 377491, 61073, '<td valign="top">I think this picture would have been better if he was actually coming up out of the ground.</td>', 'I think this picture would have been better if he was actually coming up out of the ground.', '2006-08-09 21:13:00.000000', NULL, 1),
(2712389, 377294, 61073, '<td valign="top">Nice</td>', 'Nice', '2006-08-09 21:13:16.000000', NULL, 1),
(2712391, 375611, 30637, '<td valign="top">He looks like a Hawaiian King!</td>', 'He looks like a Hawaiian King!', '2006-08-09 21:14:08.000000', NULL, 1),
