(2717812, 377204, 61679, '<td valign="top">Wonderful black and white conversion.  Bumping to a 7.</td>', 'Wonderful black and white conversion.  Bumping to a 7.', '2006-08-11 13:26:47.000000', NULL, 1),
(2717814, 376453, 59194, '<td valign="top">Great use of DOF, very nice.</td>', 'Great use of DOF, very nice.', '2006-08-11 13:26:57.000000', NULL, 1),
(2717816, 377329, 61679, '<td valign="top">Back to comment.  I love the play on words and hope you don''t get hit too badely from the DNMC crowd.  Technically, this doesn''t meet the ground up perspective of the challenge description but I''ll give you a 6 for giving me a smile this morning.</td>', 'Back to comment.  I love the play on words and hope you don''t get hit too badely from the DNMC crowd.  Technically, this doesn''t meet the ground up perspective of the challenge description but I''ll give you a 6 for giving me a smile this morning.', '2006-08-11 13:27:26.000000', NULL, 1),
(2717817, 377186, 40484, '<td valign="top">Like the composition with the pink flower against the dark mountains. Be careful of the blown highlights in the clouds.</td>', 'Like the composition with the pink flower against the dark mountains. Be careful of the blown highlights in the clouds.', '2006-08-11 13:27:35.000000', NULL, 1),
(2717818, 377234, 59194, '<td valign="top">Great colors</td>', 'Great colors', '2006-08-11 13:27:36.000000', NULL, 1),
(2717819, 376249, 61679, '<td valign="top">Back to comment.  I really like the texture presented in this image.  My only issue is the partial tree in the background.  Perhaps a different angle or different bale of hay could have presented a better background. 6</td>', 'Back to comment.  I really like the texture presented in this image.  My only issue is the partial tree in the background.  Perhaps a different angle or different bale of hay could have presented a better background. 6', '2006-08-11 13:27:39.000000', NULL, 1),
(2717827, 375761, 61679, '<td valign="top">Back to comment.   This shot appears to have the opposite perspective of the challenge description.  I hope I''m not missing something in your image that would invalidate my interpretation.</td>', 'Back to comment.   This shot appears to have the opposite perspective of the challenge description.  I hope I''m not missing something in your image that would invalidate my interpretation.', '2006-08-11 13:31:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2717836, 376706, 61679, '<td valign="top">Back to comment.  First let me start by saying I like the post processing of this image.  The coloration works well.  However, this image is hard to relate to.  Even with your title, it is hard to tell that this image has anything to do with rain.  The image meets the requirements of the challenge but the image has nothing to draw the viewer''s attention and hold it.  Maybe if the arm wasn''t in front of the child''s face.</td>', 'Back to comment.  First let me start by saying I like the post processing of this image.  The coloration works well.  However, this image is hard to relate to.  Even with your title, it is hard to tell that this image has anything to do with rain.  The image meets the requirements of the challenge but the image has nothing to draw the viewer''s attention and hold it.  Maybe if the arm wasn''t in front of the child''s face.', '2006-08-11 13:36:03.000000', NULL, 1),
(2717840, 375434, 59194, '<td valign="top">I like the tones and DOF - nice job.</td>', 'I like the tones and DOF - nice job.', '2006-08-11 13:38:56.000000', NULL, 1),
(2717868, 377421, 59390, '<td valign="top">Although the colors are nice, I feel that it DNMC.</td>', 'Although the colors are nice, I feel that it DNMC.', '2006-08-11 13:51:43.000000', NULL, 1),
(2717870, 376712, 59390, '<td valign="top">I like the colors.</td>', 'I like the colors.', '2006-08-11 13:52:20.000000', NULL, 1),
(2717877, 377604, 59390, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-08-11 13:54:39.000000', NULL, 1),
(2717881, 377540, 61679, '<td valign="top">Back to comment.  I almost did a similar shot for this challenge.  You found a good path to take the image but the camera angle is a bit flat to strongly convey the up from the ground perspective.  This image would probably score better if the whole body of the rider were visible.</td>', 'Back to comment.  I almost did a similar shot for this challenge.  You found a good path to take the image but the camera angle is a bit flat to strongly convey the up from the ground perspective.  This image would probably score better if the whole body of the rider were visible.', '2006-08-11 13:56:06.000000', NULL, 1),
(2717884, 377090, 59390, '<td valign="top">Atfirst, it looked like King Kong ontop of the Empire State Building!</td>', 'Atfirst, it looked like King Kong ontop of the Empire State Building!', '2006-08-11 13:57:25.000000', NULL, 1),
(2717888, 377190, 61679, '<td valign="top">Back to comment.  The silhouette is well done and the sky has plenty of detail to make it interesting but the blue could use a bit more saturation. This image meets the challenge but it is not a strong perspective for conveying from the ground up.</td>', 'Back to comment.  The silhouette is well done and the sky has plenty of detail to make it interesting but the blue could use a bit more saturation. This image meets the challenge but it is not a strong perspective for conveying from the ground up.', '2006-08-11 14:00:16.000000', NULL, 1),
(2717896, 377539, 61679, '<td valign="top">Back to comment.  The technicals of this image are pretty good.  Some people might say it needs a bit more saturation but I like the natural look you presented.  However, this image does not present a strong Up From The Ground Perspective.  This will probably hurt your score considerably.</td>', 'Back to comment.  The technicals of this image are pretty good.  Some people might say it needs a bit more saturation but I like the natural look you presented.  However, this image does not present a strong Up From The Ground Perspective.  This will probably hurt your score considerably.', '2006-08-11 14:04:04.000000', NULL, 1),
(2717907, 377356, 24454, '<td valign="top">This one is very good!   Such a great effect with that little bug peering over the edge of the petal.   Great job.</td>', 'This one is very good!   Such a great effect with that little bug peering over the edge of the petal.   Great job.', '2006-08-11 14:08:13.000000', NULL, 1),
(2717909, 377298, 24454, '<td valign="top">This is great.  I lile the grainy effect.   It gives it kind of a surreal look.  Great job.</td>', 'This is great.  I lile the grainy effect.   It gives it kind of a surreal look.  Great job.', '2006-08-11 14:09:11.000000', NULL, 1),
(2717911, 375659, 61679, '<td valign="top">Back to comment.  It is obvious that this shot was taken from ground level.  However, this image does not present a strong Up From The Ground Perspective.  This is partially related to the horizontal format of the image.  You also have some technical issues that are going to hurt your score.  First, the white balance gives this image a very unappealing yellow cast.  Second, the image is noisy, which causes the image to look flat and grainy.  And finally, the subject matter is less than interesting.  These look more like Condo garages than Vegas.</td>', 'Back to comment.  It is obvious that this shot was taken from ground level.  However, this image does not present a strong Up From The Ground Perspective.  This is partially related to the horizontal format of the image.  You also have some technical issues that are going to hurt your score.  First, the white balance gives this image a very unappealing yellow cast.  Second, the image is noisy, which causes the image to look flat and grainy.  And finally, the subject matter is less than interesting.  These look more like Condo garages than Vegas.', '2006-08-11 14:09:54.000000', NULL, 1),
(2717914, 377414, 24454, '<td valign="top">This is beautiful!   Those color tones and the infrared look are awesome.</td>', 'This is beautiful!   Those color tones and the infrared look are awesome.', '2006-08-11 14:11:03.000000', NULL, 1),
(2717934, 376417, 48389, '<td valign="top">Well captured, great detail. IMHO the colours could do with a little boost?</td>', 'Well captured, great detail. IMHO the colours could do with a little boost?', '2006-08-11 14:23:09.000000', NULL, 1),
(2717937, 376679, 48389, '<td valign="top">I like the colours and compostion but feel if it were straightened it would draw the eye in more (MHO)</td>', 'I like the colours and compostion but feel if it were straightened it would draw the eye in more (MHO)', '2006-08-11 14:24:03.000000', NULL, 1),
(2717939, 376604, 48389, '<td valign="top">Really like the composition and colours here :o)</td>', 'Really like the composition and colours here :o)', '2006-08-11 14:24:30.000000', NULL, 1),
(2717941, 377427, 48389, '<td valign="top">Boy do I wish I lived somewhere like this! Great choice of buildings, good colours and composition :o)</td>', 'Boy do I wish I lived somewhere like this! Great choice of buildings, good colours and composition :o)', '2006-08-11 14:25:09.000000', NULL, 1),
(2717945, 377242, 48389, '<td valign="top">Very powerful image nicely composed and the colours add to the dramatic effect :o)</td>', 'Very powerful image nicely composed and the colours add to the dramatic effect :o)', '2006-08-11 14:26:00.000000', NULL, 1),
(2717947, 377112, 48389, '<td valign="top">Nice clouds and viewpoint</td>', 'Nice clouds and viewpoint', '2006-08-11 14:27:01.000000', NULL, 1),
(2717952, 374848, 48389, '<td valign="top">A different subject, nicely lit but feel more detail at the bottom would add to the impact (MHO)</td>', 'A different subject, nicely lit but feel more detail at the bottom would add to the impact (MHO)', '2006-08-11 14:28:34.000000', NULL, 1),
(2717955, 374857, 48389, '<td valign="top">I like the idea but the image doesnt really have any wow factor (MHO)</td>', 'I like the idea but the image doesnt really have any wow factor (MHO)', '2006-08-11 14:29:55.000000', NULL, 1),
(2717956, 377544, 61191, '<td valign="top">Love the straight lines and the sunrays.</td>', 'Love the straight lines and the sunrays.', '2006-08-11 14:29:56.000000', NULL, 1),
(2717968, 376439, 48389, '<td valign="top">Great choice of viewpoint but the clouds look a little ''odd'' to me (MHO)</td>', 'Great choice of viewpoint but the clouds look a little ''odd'' to me (MHO)', '2006-08-11 14:33:15.000000', NULL, 1),
(2717971, 374931, 48389, '<td valign="top">Nice viewpoint and I like the colours but it seems slightly out of focus (could be my eyes though!!) :o)</td>', 'Nice viewpoint and I like the colours but it seems slightly out of focus (could be my eyes though!!) :o)', '2006-08-11 14:34:41.000000', NULL, 1),
(2717974, 376127, 48389, '<td valign="top">what a lovely place to be! well exposed and I like the feeling of ''on top of the world'' that this image gives :o)</td>', 'what a lovely place to be! well exposed and I like the feeling of ''on top of the world'' that this image gives :o)', '2006-08-11 14:35:32.000000', NULL, 1),
(2717978, 377457, 48389, '<td valign="top">This is a ncie image but does give me the feeling ''from the ground up'' (MHO)</td>', 'This is a ncie image but does give me the feeling ''from the ground up'' (MHO)', '2006-08-11 14:36:03.000000', NULL, 1),
(2718165, 376065, 48389, '<td valign="top">the sign gives the viewer a good perspective and I like the colour and detail in the castle :o)</td>', 'the sign gives the viewer a good perspective and I like the colour and detail in the castle :o)', '2006-08-11 15:34:52.000000', NULL, 1),
(2718176, 374751, 48389, '<td valign="top">The wires make a great effect and the light at the top of the mast is really nice :o)</td>', 'The wires make a great effect and the light at the top of the mast is really nice :o)', '2006-08-11 15:37:48.000000', NULL, 1),
(2718182, 375611, 48389, '<td valign="top">For a second I thought the cat was swinging from the light fitting!!! Good angle and I like that you have the cat looking straight at you. I feel this would have worked better without the fan/light behind the cats head and slightly different lighting (MHO)</td>', 'For a second I thought the cat was swinging from the light fitting!!! Good angle and I like that you have the cat looking straight at you. I feel this would have worked better without the fan/light behind the cats head and slightly different lighting (MHO)', '2006-08-11 15:39:01.000000', NULL, 1),
(2718196, 375421, 48389, '<td valign="top">I like the perspective and certainly gives the view of looking a long long way up :o)</td>', 'I like the perspective and certainly gives the view of looking a long long way up :o)', '2006-08-11 15:42:32.000000', NULL, 1),
(2718200, 377228, 48389, '<td valign="top">I like the choice of tree, great branches giving a kind of spiral effect. I would like to see the base of the tree more in focus to help lead my eye into the shot (MHO)</td>', 'I like the choice of tree, great branches giving a kind of spiral effect. I would like to see the base of the tree more in focus to help lead my eye into the shot (MHO)', '2006-08-11 15:43:30.000000', NULL, 1),
(2718213, 377559, 48389, '<td valign="top">Love the idea , the image seems a bit noisy to me and I would like to have seen the ''person'' a little more in focus and with some more detail (MHO) :o)</td>', 'Love the idea , the image seems a bit noisy to me and I would like to have seen the ''person'' a little more in focus and with some more detail (MHO) :o)', '2006-08-11 15:47:29.000000', NULL, 1),
(2718215, 376946, 48389, '<td valign="top">what a great structure, nice choice of angle :o)</td>', 'what a great structure, nice choice of angle :o)', '2006-08-11 15:48:18.000000', NULL, 1),
(2718216, 375997, 52336, '<td valign="top">Lovely, gorgeous use of negative space and breathtaking contrasts...</td>', 'Lovely, gorgeous use of negative space and breathtaking contrasts...', '2006-08-11 15:48:19.000000', NULL, 1),
(2718219, 375694, 48389, '<td valign="top">I like the colours and detail you have captured here but this doesnt feel like ''looking up'' (MHO)</td>', 'I like the colours and detail you have captured here but this doesnt feel like ''looking up'' (MHO)', '2006-08-11 15:48:53.000000', NULL, 1),
(2718227, 377559, 52336, '<td valign="top">Nice view that shows off the great lines and intersections of this bridge.  A bit blown at the opening to the bridge, and overall a tad flat, but a neat photograph nonetheless.</td>', 'Nice view that shows off the great lines and intersections of this bridge.  A bit blown at the opening to the bridge, and overall a tad flat, but a neat photograph nonetheless.', '2006-08-11 15:52:43.000000', NULL, 1),
(2718237, 377329, 52336, '<td valign="top">:)</td>', ':)', '2006-08-11 15:57:57.000000', NULL, 1),
(2718241, 377269, 52336, '<td valign="top">Wow, gorgeous and dramatic, a lovely photograph.</td>', 'Wow, gorgeous and dramatic, a lovely photograph.', '2006-08-11 15:59:17.000000', NULL, 1),
(2718267, 375434, 52336, '<td valign="top">This is pretty cool... it''s an interesting way of having seen this everyday object.</td>', 'This is pretty cool... it''s an interesting way of having seen this everyday object.', '2006-08-11 16:06:32.000000', NULL, 1),
(2718272, 376419, 52336, '<td valign="top">That''s a pretty awesome use of shadow, negative space, etc... what a great photograph.</td>', 'That''s a pretty awesome use of shadow, negative space, etc... what a great photograph.', '2006-08-11 16:08:27.000000', NULL, 1),
(2718308, 375439, 37444, '<td valign="top">Very cool; I might have angled the building just a bit more. 8</td>', 'Very cool; I might have angled the building just a bit more. 8', '2006-08-11 16:20:29.000000', NULL, 1),
