(2718490, 376975, 40370, '<td valign="top">Cute title but unfortunately it won''t carry the image past a 5 for me, you''ve met the challenge but the washed out sky and burned out leaves render the image deary. I wish the detail of the wood grain was the highlight.</td>', 'Cute title but unfortunately it won''t carry the image past a 5 for me, you''ve met the challenge but the washed out sky and burned out leaves render the image deary. I wish the detail of the wood grain was the highlight.', '2006-08-11 17:12:59.000000', NULL, 1),
(2718494, 377186, 40370, '<td valign="top">Beautiful ... but the perspective is too staight-on to cause a "wow" from me. 5</td>', 'Beautiful ... but the perspective is too staight-on to cause a "wow" from me. 5', '2006-08-11 17:14:36.000000', NULL, 1),
(2718495, 377457, 61191, '<td valign="top">Wow! Lovely shot!</td>', 'Wow! Lovely shot!', '2006-08-11 17:16:22.000000', NULL, 1),
(2718497, 377359, 40370, '<td valign="top">What a structure, nice perspective, I might have tried to tweak the blues just a bit for more "pop", a bump in contrast too.</td>', 'What a structure, nice perspective, I might have tried to tweak the blues just a bit for more "pop", a bump in contrast too.', '2006-08-11 17:16:53.000000', NULL, 1),
(2718498, 376802, 61191, '<td valign="top">Great light and colors!</td>', 'Great light and colors!', '2006-08-11 17:17:22.000000', NULL, 1),
(2718502, 377544, 40370, '<td valign="top">Nice capture of the wood grain, the color looks saturated but still very real looking. I don''t care for the sunglare but some voters like it. Good Luck.</td>', 'Nice capture of the wood grain, the color looks saturated but still very real looking. I don''t care for the sunglare but some voters like it. Good Luck.', '2006-08-11 17:18:07.000000', NULL, 1),
(2718503, 377180, 61191, '<td valign="top">That''s a real eye-cachter! Lighting is outstanding!</td>', 'That''s a real eye-cachter! Lighting is outstanding!', '2006-08-11 17:18:24.000000', NULL, 1),
