(2718522, 377213, 40370, '<td valign="top">The old door with the cracked plaster and greenery around it is classic. However, for this challenge, the angle from the street does not do it justice, and the street stones (slightly out of focus) do not compliment this perspective. I''d save this address because if you can go back to this old structure I predict a fabulous image that will fit a future challenge splendidly. 5</td>', 'The old door with the cracked plaster and greenery around it is classic. However, for this challenge, the angle from the street does not do it justice, and the street stones (slightly out of focus) do not compliment this perspective. I''d save this address because if you can go back to this old structure I predict a fabulous image that will fit a future challenge splendidly. 5', '2006-08-11 17:23:52.000000', NULL, 1),
(2718525, 375960, 40370, '<td valign="top">Vivid. Unexpected.</td>', 'Vivid. Unexpected.', '2006-08-11 17:24:40.000000', NULL, 1),
