(2722138, 375369, 48389, '<td valign="top">Beautiful composition and conversion :o)</td>', 'Beautiful composition and conversion :o)', '2006-08-13 08:11:01.000000', NULL, 1),
(2722140, 375262, 16912, '<td valign="top">Lovely take on the challenge :) I''ve been thinking about shooting some golf for a while and when I do this is one of my ''wishlist'' shots. A couple of points I think may improve the shot would be to have had an empty background (no trees buildings etc) and to me his stance doesn''t look too hot for a golfer? nice shot and good luck ;) (7)</td>', 'Lovely take on the challenge :) I''ve been thinking about shooting some golf for a while and when I do this is one of my ''wishlist'' shots. A couple of points I think may improve the shot would be to have had an empty background (no trees buildings etc) and to me his stance doesn''t look too hot for a golfer? nice shot and good luck ;) (7)', '2006-08-13 08:18:25.000000', NULL, 1),
(2722142, 376987, 16912, '<td valign="top">I think this would have been a nice image if it wasn''t for the post processing :(</td>', 'I think this would have been a nice image if it wasn''t for the post processing :(', '2006-08-13 08:21:33.000000', NULL, 1),
