(2729897, 377346, 62095, '<td valign="top">For me in this shot the angle makes it more like a from the ground down shot.  Also the greenery over to the left is distracting from the decent waterfall.</td>', 'For me in this shot the angle makes it more like a from the ground down shot.  Also the greenery over to the left is distracting from the decent waterfall.', '2006-08-15 16:21:58.000000', NULL, 1),
(2729899, 375876, 62095, '<td valign="top">Captures the challenge well and you''ve got a mini leaning tower of pisa in the background. ;) Shame about the vignetting.</td>', 'Captures the challenge well and you''ve got a mini leaning tower of pisa in the background. ;) Shame about the vignetting.', '2006-08-15 16:23:52.000000', NULL, 1),
